changeSet.sql:
CREATE TABLE IF NOT EXISTS votality_codigos_sms (
    id BIGSERIAL PRIMARY KEY,
    telefono VARCHAR(20) NOT NULL,
    codigo VARCHAR(6) NOT NULL,
    motivo VARCHAR(20) NOT NULL,
    creado_el TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    expira_el TIMESTAMP WITH TIME ZONE NOT NULL,
    usado BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE INDEX IF NOT EXISTS idx_codigos_sms_telefono ON votality_codigos_sms(telefono);
CREATE INDEX IF NOT EXISTS idx_codigos_sms_telefono_motivo ON votality_codigos_sms(telefono, motivo);
CREATE INDEX IF NOT EXISTS idx_codigos_sms_usado_expira ON votality_codigos_sms(usado, expira_el);
